mapper.select:
SELECT doc_code AS asset_code, doc_name AS asset_name, project_id, system_code, #{assetType} AS asset_type, CAST(structured_data AS CHAR) AS structured_data FROM ${table} WHERE tenant_id = #{tenantId} AND project_id = #{projectId} AND deleted = 0 AND system_code = #{systemCode}
AND (doc_code LIKE CONCAT('%', #{keyword}, '%') OR doc_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id
